package com.agentguard.service;
import com.agentguard.dto.*; import com.agentguard.entity.PurchasePolicy; import com.agentguard.exception.ResourceNotFoundException; import com.agentguard.repository.*; import org.junit.jupiter.api.*; import org.mockito.*; import java.math.BigDecimal; import java.util.*; import static org.assertj.core.api.Assertions.*; import static org.mockito.Mockito.*;
class PolicyServiceTest { @Mock PurchasePolicyRepository policies; @Mock UserRepository users; @InjectMocks PolicyService service; @BeforeEach void setup(){MockitoAnnotations.openMocks(this);} @Test void createsPolicyForExistingUser(){when(users.existsById(1L)).thenReturn(true);when(policies.save(any())).thenAnswer(i->i.getArgument(0));PolicyResponse response=service.create(new CreatePolicyRequest(1L,"software",new BigDecimal("200.00"),true,true));assertThat(response.category()).isEqualTo("software");verify(policies).save(any(PurchasePolicy.class));} @Test void rejectsPolicyForUnknownUser(){when(users.existsById(9L)).thenReturn(false);assertThatThrownBy(()->service.create(new CreatePolicyRequest(9L,"software",new BigDecimal("200"),false,true))).isInstanceOf(ResourceNotFoundException.class);verify(policies,never()).save(any());} @Test void listsPolicies(){when(users.existsById(1L)).thenReturn(true);PurchasePolicy p=new PurchasePolicy();p.setUserId(1L);p.setCategory("travel");p.setMaxAmount(new BigDecimal("500"));p.setActive(true);when(policies.findByUserIdOrderByCreatedAtDesc(1L)).thenReturn(List.of(p));assertThat(service.getForUser(1L)).hasSize(1);}}
